const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');

  const projectId = $input.first().json.params?.id;
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project id required in path' } }];
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(projectId)) {
    return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project id must be UUID' } }];
  }

  return [{ json: {
    user_id:    payload.sub,
    tenant_id:  payload.tenant_id || null,
    role:       payload.role || 'architect',
    project_id: projectId,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const project = $input.first()?.json;
const sess    = $('Decode JWT + Path').first().json;

if (!project || !project.id) {
  return [{ json: { _error: 'NOT_FOUND', _status: 404, _details: 'Project ' + sess.project_id + ' no encontrado o sin permisos', request_id: sess.request_id } }];
}

return [{ json: {
  data: {
    id:                project.id,
    name:              project.name,
    client_name:       project.client_name,
    current_phase:     project.current_phase,
    status:            project.status,
    project_type:      project.project_type,
    property_type:     project.property_type,
    property_area_m2:  project.property_area_m2 ? parseFloat(project.property_area_m2) : null,
    location_address:  project.location_address,
    location_city:     project.location_city,
    location_province: project.location_province,
    budget_target:     project.budget_target ? parseFloat(project.budget_target) : null,
    urgency:           project.urgency,
    created_at:        project.created_at,
    updated_at:        project.updated_at,
    metadata:          project.metadata,
    briefing:             project.briefing,
    design_options:       project.design_options || [],
    regulatory_tasks:     project.regulatory_tasks || [],
    cost_estimate:        project.cost_estimate,
    proposal:             project.proposal,
    project_plan:         project.project_plan,
    safety_plan:          project.safety_plan,
    accessibility_audits: project.accessibility_audits || []
  },
  meta: {
    request_id: sess.request_id,
    timestamp:  new Date().toISOString()
  }
}}];
